var FALLBACK_TEMPLATE_KEY = "Other Celebration";
function parseHoursBefore(raw) {
  const match2 = raw.trim().toLowerCase().match(/^([\d.]+)\s*hr before$/);
  if (!match2) return null;
  const hours = parseFloat(match2[1]);
  return Number.isFinite(hours) ? hours : null;
}
function formatHoursBefore(hours) {
  const rounded = Math.round(hours * 10) / 10;
  return `${rounded % 1 === 0 ? rounded : rounded.toFixed(1)} hr before`;
}
function requiredSetupHours(guestCount) {
  if (guestCount > 100) return 3;
  if (guestCount > 60) return 2;
  if (guestCount > 25) return 1.5;
  return 1;
}
var STAGGERED_ARRIVAL_THRESHOLD = 75;
function generateTimeline(input) {
  const template = BASE_TEMPLATES[input.eventType] ?? BASE_TEMPLATES[FALLBACK_TEMPLATE_KEY];
  const guestCount = Math.max(0, input.guestCount || 0);
  const needed = requiredSetupHours(guestCount);
  const scaled = template.map((item) => {
    if (item.category !== "Setup") return item;
    const existingHours = parseHoursBefore(item.time);
    if (existingHours === null || existingHours >= needed) return item;
    return { ...item, time: formatHoursBefore(needed) };
  });
  const withArrival = [];
  for (let i = 0; i < scaled.length; i++) {
    withArrival.push(scaled[i]);
    const isLastArrivalItem = scaled[i].category === "Arrival" && (i === scaled.length - 1 || scaled[i + 1].category !== "Arrival");
    if (isLastArrivalItem && guestCount > STAGGERED_ARRIVAL_THRESHOLD) {
      withArrival.push({
        time: "+20 min",
        title: "Guests continue arriving (staggered)",
        category: "Arrival"
      });
    }
  }
  const alreadyMentionsCake = withArrival.some((item) => item.title.toLowerCase().includes("cake"));
  const result = [];
  let inserted = false;
  for (let i = 0; i < withArrival.length; i++) {
    result.push({ ...withArrival[i], sortOrder: 0 });
    const isLastFoodItem = withArrival[i].category === "Food & Toasts" && (i === withArrival.length - 1 || withArrival[i + 1].category !== "Food & Toasts");
    if (isLastFoodItem && input.hasCakeMenuItem && !alreadyMentionsCake && !inserted) {
      result.push({
        time: "Shortly after the meal",
        title: "Cake cutting",
        category: "Special Moments",
        sortOrder: 0
      });
      inserted = true;
    }
  }
  return result.map((item, index2) => ({ ...item, sortOrder: index2 }));
}

// shared/guestCount.ts
function resolveGuestCount(estimatedGuestCount, guests2) {
  if (guests2.length > 0) {
    const invitedHeadcount = guests2.reduce((sum, g) => sum + g.partySize, 0);
    const confirmedHeadcount = guests2.filter((g) => g.rsvpStatus === "yes").reduce((sum, g) => sum + (g.attendingCount ?? g.partySize), 0);
    const headcount = confirmedHeadcount > 0 ? confirmedHeadcount : invitedHeadcount;
    if (headcount > 0) return headcount;
  }
  if (typeof estimatedGuestCount === "number" && estimatedGuestCount > 0) {
    return estimatedGuestCount;
  }
  return 1;
}

